/** A list of [`LIST_LEN`] items with operations that change one item at a time. */
export class BigList extends UndraStore {
  readonly items: Signal<Item[]> = new Signal<Item[]>([]);
  /** Computed by the core; read-only. */
  readonly count: Signal<number> = new Signal<number>(0);

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle);
    this._signals = [this.items, this.count];
  }

  /**
   * A list of [`LIST_LEN`] items numbered from 1.
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  static async create(core: UndraCore = UndraPlaygroundCore.core): Promise<BigList> {
    let handle: bigint;
    try {
      handle = await core.construct(
        UndraIds.Objects.BigList.typeId,
        UndraIds.Objects.BigList.new,
        new Uint8Array(0),
      );
    } catch (error) {
      throw UndraCallError.mapped(error);
    }
    const store = new BigList(core, handle);
    await store._observeAll();
    return store;
  }

  /**
   * Inserts a new row with `label` so that it ends at `index` (`index == len` appends), and
   * returns its identity. One keyed `Insert`.
   * @throws {ListError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  async insertAt(index: number, label: string): Promise<number> {
    const w = new UndraWriter();
    w.writeU32(index);
    w.writeStr(label);
    try {
      const body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.insertAt,
        w.finish(),
      );
      return decodeValue(codecs.u32, body);
    } catch (error) {
      throw UndraCallError.mapped(error, ListErrorCodec);
    }
  }

  /**
   * Moves the row at `from` so that it ends at `to`. One keyed `Move`.
   * @throws {ListError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  async moveItem(from: number, to: number): Promise<void> {
    const w = new UndraWriter();
    w.writeU32(from);
    w.writeU32(to);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.moveItem,
        w.finish(),
      );
    } catch (error) {
      throw UndraCallError.mapped(error, ListErrorCodec);
    }
  }

  /**
   * Removes the row at `index`. One keyed `Remove`.
   * @throws {ListError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  async removeAt(index: number): Promise<void> {
    const w = new UndraWriter();
    w.writeU32(index);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.removeAt,
        w.finish(),
      );
    } catch (error) {
      throw UndraCallError.mapped(error, ListErrorCodec);
    }
  }

  /**
   * Replaces the list with a fresh one of [`LIST_LEN`] items. The platform receives the keyed
   * patch that turns the old list into the new one (a full value if they have little in
   * common).
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async reset(): Promise<void> {
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.reset,
        new Uint8Array(0),
      );
    } catch (error) {
      this.core.report(error, "BigList.reset");
    }
  }

  /**
   * Changes the label of the row at `index` and bumps its version. One keyed `Update`.
   * @throws {ListError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  async updateAt(index: number, label: string): Promise<void> {
    const w = new UndraWriter();
    w.writeU32(index);
    w.writeStr(label);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.BigList.updateAt,
        w.finish(),
      );
    } catch (error) {
      throw UndraCallError.mapped(error, ListErrorCodec);
    }
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    try {
      switch (signalId) {
        case 0:
          if (op === ChangeOp.FullValue) {
            this.items._set(decodeValue(vecItem, value));
          } else if (op === ChangeOp.KeyedPatch) {
            const r = new UndraReader(value);
            const ops = decodePatch(r, ItemCodec);
            r.finish();
            try {
              this.items._set(applyPatch(this.items.peek(), ops));
            } catch (error) {
              if (!(error instanceof PatchError)) throw error;
              this._resync(0);
            }
          }
          break;
        case 1:
          if (op === ChangeOp.FullValue) {
            this.count._set(decodeValue(codecs.u32, value));
          }
          break;
        default:
          break;
      }
    } catch (error) {
      this.core.report(error, `BigList.apply(signal: ${signalId})`);
    }
  }

  /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
  private _resync(signalId: number): void {
    for (const on of [false, true]) {
      this.core.observe(this.handle, signalId, on).catch((error: unknown) => {
        this.core.report(error, `BigList.resync(signal: ${signalId})`);
      });
    }
  }
}

/** A counter with a change tally and a computed parity. */
export class Counter extends UndraStore {
  readonly count: Signal<number> = new Signal<number>(0);
  readonly changes: Signal<number> = new Signal<number>(0);
  /** Computed by the core; read-only. */
  readonly parity: Signal<Parity> = new Signal<Parity>("even");

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle);
    this._signals = [this.count, this.changes, this.parity];
  }

  /**
   * A counter at zero with no changes made.
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  static async create(core: UndraCore = UndraPlaygroundCore.core): Promise<Counter> {
    let handle: bigint;
    try {
      handle = await core.construct(
        UndraIds.Objects.Counter.typeId,
        UndraIds.Objects.Counter.new,
        new Uint8Array(0),
      );
    } catch (error) {
      throw UndraCallError.mapped(error);
    }
    const store = new Counter(core, handle);
    await store._observeAll();
    return store;
  }

  /**
   * Adds `amount` (which may be negative) and counts the change: one transaction, so one
   * change-set for `count`, `changes` and `parity` together. The count saturates instead of
   * overflowing.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async add(amount: number): Promise<void> {
    try {
      const w = new UndraWriter();
      w.writeI32(amount);
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Counter.add,
        w.finish(),
      );
    } catch (error) {
      this.core.report(error, "Counter.add");
    }
  }

  /**
   * Subtracts one.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async decrement(): Promise<void> {
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Counter.decrement,
        new Uint8Array(0),
      );
    } catch (error) {
      this.core.report(error, "Counter.decrement");
    }
  }

  /**
   * Adds one.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async increment(): Promise<void> {
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Counter.increment,
        new Uint8Array(0),
      );
    } catch (error) {
      this.core.report(error, "Counter.increment");
    }
  }

  /**
   * Sets the count back to zero and forgets the changes, in one transaction.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async reset(): Promise<void> {
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Counter.reset,
        new Uint8Array(0),
      );
    } catch (error) {
      this.core.report(error, "Counter.reset");
    }
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    try {
      switch (signalId) {
        case 0:
          if (op === ChangeOp.FullValue) {
            this.count._set(decodeValue(codecs.i32, value));
          }
          break;
        case 1:
          if (op === ChangeOp.FullValue) {
            this.changes._set(decodeValue(codecs.u32, value));
          }
          break;
        case 2:
          if (op === ChangeOp.FullValue) {
            this.parity._set(decodeValue(ParityCodec, value));
          }
          break;
        default:
          break;
      }
    } catch (error) {
      this.core.report(error, `Counter.apply(signal: ${signalId})`);
    }
  }
}

/**
 * The `Connectivity` and `Lifecycle` reports as the core received them: the last of each and how
 * many there were since the core started. Every report moves the signals in one transaction, and
 * every signal is `no_coalesce`: a platform's mirror applies each report, even several that arrive
 * in one frame (or while the app is in the background, where React Native on Android pauses the
 * timers that drain it), so a UI or a check sees `background` even when `active` follows at once.
 */
export class Device extends UndraStore {
  readonly online: Signal<boolean> = new Signal<boolean>(false);
  readonly netKind: Signal<NetKind> = new Signal<NetKind>("wifi");
  readonly appState: Signal<AppState> = new Signal<AppState>("active");
  readonly connectivityReports: Signal<number> = new Signal<number>(0);
  readonly lifecycleReports: Signal<number> = new Signal<number>(0);

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle, { noCoalesce: [0, 1, 2, 3, 4] });
    this._signals = [
      this.online,
      this.netKind,
      this.appState,
      this.connectivityReports,
      this.lifecycleReports,
    ];
  }

  /**
   * The store, showing every report received so far and following the next ones.
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  static async create(core: UndraCore = UndraPlaygroundCore.core): Promise<Device> {
    let handle: bigint;
    try {
      handle = await core.construct(
        UndraIds.Objects.Device.typeId,
        UndraIds.Objects.Device.new,
        new Uint8Array(0),
      );
    } catch (error) {
      throw UndraCallError.mapped(error);
    }
    const store = new Device(core, handle);
    await store._observeAll();
    return store;
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    try {
      switch (signalId) {
        case 0:
          if (op === ChangeOp.FullValue) {
            this.online._set(decodeValue(codecs.bool, value));
          }
          break;
        case 1:
          if (op === ChangeOp.FullValue) {
            this.netKind._set(decodeValue(NetKindCodec, value));
          }
          break;
        case 2:
          if (op === ChangeOp.FullValue) {
            this.appState._set(decodeValue(AppStateCodec, value));
          }
          break;
        case 3:
          if (op === ChangeOp.FullValue) {
            this.connectivityReports._set(decodeValue(codecs.u32, value));
          }
          break;
        case 4:
          if (op === ChangeOp.FullValue) {
            this.lifecycleReports._set(decodeValue(codecs.u32, value));
          }
          break;
        default:
          break;
      }
    } catch (error) {
      this.core.report(error, `Device.apply(signal: ${signalId})`);
    }
  }
}

