/** The notes of one database, mirrored: `notes` changes only after the database did. */
export class Notes extends UndraStore {
  readonly notes: Signal<Note[]> = new Signal<Note[]>([]);
  readonly version: Signal<number> = new Signal<number>(0);

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle);
    this._signals = [this.notes, this.version];
  }

  /**
   * No database open yet: call [`open`](Notes::open).
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  static async create(core: UndraCore = UndraPlaygroundCore.core): Promise<Notes> {
    let handle: bigint;
    try {
      handle = await core.construct(
        UndraIds.Objects.Notes.typeId,
        UndraIds.Objects.Notes.new,
        new Uint8Array(0),
      );
    } catch (error) {
      throw UndraCallError.mapped(error);
    }
    const store = new Notes(core, handle);
    await store._observeAll();
    return store;
  }

  /**
   * Adds a note at the end.
   * @throws {DbError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async add(title: string, signal?: AbortSignal): Promise<Note> {
    const w = new UndraWriter();
    w.writeStr(title);
    try {
      const body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Notes.add,
        w.finish(),
        signal,
      );
      return decodeValue(NoteCodec, body);
    } catch (error) {
      throw UndraCallError.mapped(error, DbErrorCodec);
    }
  }

  /**
   * Adds every title in one transaction: all or none. A `None` title breaks `NOT NULL` and
   * rolls the whole batch back. Returns how many were added.
   * @throws {DbError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async addAll(titles: (string | null)[], signal?: AbortSignal): Promise<number> {
    const w = new UndraWriter();
    vecOptionString.encode(w, titles);
    try {
      const body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Notes.addAll,
        w.finish(),
        signal,
      );
      return decodeValue(codecs.u32, body);
    } catch (error) {
      throw UndraCallError.mapped(error, DbErrorCodec);
    }
  }

  /**
   * Adds a note with a chosen id (an id in use is `Constraint { kind: Unique }`).
   * @throws {DbError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async addWithId(id: bigint, title: string, signal?: AbortSignal): Promise<Note> {
    const w = new UndraWriter();
    w.writeI64(id);
    w.writeStr(title);
    try {
      const body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Notes.addWithId,
        w.finish(),
        signal,
      );
      return decodeValue(NoteCodec, body);
    } catch (error) {
      throw UndraCallError.mapped(error, DbErrorCodec);
    }
  }

  /**
   * Closes the database; the list keeps what it showed (`close` is every store's own: it
   * releases the handle).
   * @throws {DbError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async closeDatabase(signal?: AbortSignal): Promise<void> {
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Notes.closeDatabase,
        new Uint8Array(0),
        signal,
      );
    } catch (error) {
      throw UndraCallError.mapped(error, DbErrorCodec);
    }
  }

  /**
   * How many notes the database holds (read from it, not from the mirror).
   * @throws {DbError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async count(signal?: AbortSignal): Promise<number> {
    try {
      const body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Notes.count,
        new Uint8Array(0),
        signal,
      );
      return decodeValue(codecs.u32, body);
    } catch (error) {
      throw UndraCallError.mapped(error, DbErrorCodec);
    }
  }

  /**
   * Opens (creating it if needed) database `name`, migrates it and loads every note.
   * Returns its version.
   * @throws {DbError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async open(name: string, signal?: AbortSignal): Promise<number> {
    const w = new UndraWriter();
    w.writeStr(name);
    try {
      const body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Notes.open,
        w.finish(),
        signal,
      );
      return decodeValue(codecs.u32, body);
    } catch (error) {
      throw UndraCallError.mapped(error, DbErrorCodec);
    }
  }

  /**
   * Removes note `id`.
   * @throws {DbError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async remove(id: bigint, signal?: AbortSignal): Promise<void> {
    const w = new UndraWriter();
    w.writeI64(id);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Notes.remove,
        w.finish(),
        signal,
      );
    } catch (error) {
      throw UndraCallError.mapped(error, DbErrorCodec);
    }
  }

  /**
   * Ticks or unticks note `id`.
   * @throws {DbError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async toggle(id: bigint, signal?: AbortSignal): Promise<void> {
    const w = new UndraWriter();
    w.writeI64(id);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Notes.toggle,
        w.finish(),
        signal,
      );
    } catch (error) {
      throw UndraCallError.mapped(error, DbErrorCodec);
    }
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    try {
      switch (signalId) {
        case 0:
          if (op === ChangeOp.FullValue) {
            this.notes._set(decodeValue(vecNote, value));
          } else if (op === ChangeOp.KeyedPatch) {
            const r = new UndraReader(value);
            const ops = decodePatch(r, NoteCodec);
            r.finish();
            try {
              this.notes._set(applyPatch(this.notes.peek(), ops));
            } catch (error) {
              if (!(error instanceof PatchError)) throw error;
              this._resync(0);
            }
          }
          break;
        case 1:
          if (op === ChangeOp.FullValue) {
            this.version._set(decodeValue(codecs.u32, value));
          }
          break;
        default:
          break;
      }
    } catch (error) {
      this.core.report(error, `Notes.apply(signal: ${signalId})`);
    }
  }

  /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
  private _resync(signalId: number): void {
    for (const on of [false, true]) {
      this.core.observe(this.handle, signalId, on).catch((error: unknown) => {
        this.core.report(error, `Notes.resync(signal: ${signalId})`);
      });
    }
  }
}

