/**
 * A store that commits many transactions, for the coalesced-delivery scenarios and the
 * playground's stress screen.
 */
export class Stress extends UndraStore {
  readonly value: Signal<bigint> = new Signal<bigint>(0n);
  readonly progress: Signal<number> = new Signal<number>(0);
  readonly generated: Signal<bigint> = new Signal<bigint>(0n);
  readonly running: Signal<boolean> = new Signal<boolean>(false);

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle, { noCoalesce: [1] });
    this._signals = [this.value, this.progress, this.generated, this.running];
  }

  /**
   * A store with every signal at its start: zeros, and no generator running.
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  static async create(core: UndraCore = UndraPlaygroundCore.core): Promise<Stress> {
    let handle: bigint;
    try {
      handle = await core.construct(
        UndraIds.Objects.Stress.typeId,
        UndraIds.Objects.Stress.new,
        new Uint8Array(0),
      );
    } catch (error) {
      throw UndraCallError.mapped(error);
    }
    const store = new Stress(core, handle);
    await store._observeAll();
    return store;
  }

  /**
   * Commits `transactions` transactions now, each one write of the signal `mode` names: one
   * change-set per transaction, the way data that arrives in the core on its own does.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async burst(mode: StressMode, transactions: number): Promise<void> {
    try {
      const w = new UndraWriter();
      StressModeCodec.encode(w, mode);
      w.writeU32(transactions);
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Stress.burst,
        w.finish(),
      );
    } catch (error) {
      this.core.report(error, "Stress.burst");
    }
  }

  /**
   * Starts generating updates of the signal the mode names, at the given number a second,
   * each its own transaction, until `stop`. Called while a generator runs, it retunes that
   * generator (new mode, new rate) instead of starting a second one. Fails, starting
   * nothing, when the rate is zero or above 1,000,000.
   * @throws {StressError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  async start(mode: StressMode, perSecond: number): Promise<void> {
    const w = new UndraWriter();
    StressModeCodec.encode(w, mode);
    w.writeU32(perSecond);
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Stress.start,
        w.finish(),
      );
    } catch (error) {
      throw UndraCallError.mapped(error, StressErrorCodec);
    }
  }

  /**
   * Stops the generator: no update is committed after this returns. `generated` keeps its
   * count. Does nothing when no generator runs.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async stop(): Promise<void> {
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Stress.stop,
        new Uint8Array(0),
      );
    } catch (error) {
      this.core.report(error, "Stress.stop");
    }
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    try {
      switch (signalId) {
        case 0:
          if (op === ChangeOp.FullValue) {
            this.value._set(decodeValue(codecs.u64, value));
          }
          break;
        case 1:
          if (op === ChangeOp.FullValue) {
            this.progress._set(decodeValue(codecs.u32, value));
          }
          break;
        case 2:
          if (op === ChangeOp.FullValue) {
            this.generated._set(decodeValue(codecs.u64, value));
          }
          break;
        case 3:
          if (op === ChangeOp.FullValue) {
            this.running._set(decodeValue(codecs.bool, value));
          }
          break;
        default:
          break;
      }
    } catch (error) {
      this.core.report(error, `Stress.apply(signal: ${signalId})`);
    }
  }
}

/** The to-do list: what the UI observes (`todos`, `filter`, `visible`, `remaining`) and calls. */
export class Todos extends UndraStore {
  readonly todos: Signal<Todo[]> = new Signal<Todo[]>([]);
  readonly filter: Signal<Filter> = new Signal<Filter>("all");
  /** Derived by the core from another list; read-only. Changes arrive as keyed patches. */
  readonly visible: Signal<Todo[]> = new Signal<Todo[]>([]);
  /** Computed by the core; read-only. */
  readonly remaining: Signal<number> = new Signal<number>(0);

  private constructor(core: UndraCore, handle: bigint) {
    super(core, handle);
    this._signals = [this.todos, this.filter, this.visible, this.remaining];
  }

  /**
   * An empty list showing every item.
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   */
  static async create(core: UndraCore = UndraPlaygroundCore.core): Promise<Todos> {
    let handle: bigint;
    try {
      handle = await core.construct(
        UndraIds.Objects.Todos.typeId,
        UndraIds.Objects.Todos.new,
        new Uint8Array(0),
      );
    } catch (error) {
      throw UndraCallError.mapped(error);
    }
    const store = new Todos(core, handle);
    await store._observeAll();
    return store;
  }

  /**
   * Adds an item at the end of the list.
   * @throws {TodoError}
   * @throws {UndraCallError} If the core panics, refuses or cancels the call, or cannot be reached.
   * @throws The `signal`'s reason (an `AbortError` by default) if it aborts the call.
   */
  async add(title: string, signal?: AbortSignal): Promise<Todo> {
    const w = new UndraWriter();
    w.writeStr(title);
    try {
      const body = await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Todos.add,
        w.finish(),
        signal,
      );
      return decodeValue(TodoCodec, body);
    } catch (error) {
      throw UndraCallError.mapped(error, TodoErrorCodec);
    }
  }

  /**
   * Removes every finished item.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async clearDone(): Promise<void> {
    try {
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Todos.clearDone,
        new Uint8Array(0),
      );
    } catch (error) {
      this.core.report(error, "Todos.clearDone");
    }
  }

  /**
   * Appends `count` items titled `Item 1`, `Item 2`, .. with every fourth one finished, in one
   * transaction (a demo and test helper: the big-list screen of the docs, contract scenario S19).
   * A bulk load is a raw write, so `todos` and `visible` are sent as full values this once; the
   * writes after it are patches again.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async fill(count: number): Promise<void> {
    try {
      const w = new UndraWriter();
      w.writeU32(count);
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Todos.fill,
        w.finish(),
      );
    } catch (error) {
      this.core.report(error, "Todos.fill");
    }
  }

  /**
   * Removes the item with `id`; unknown ids are ignored.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async remove(id: string): Promise<void> {
    try {
      const w = new UndraWriter();
      w.writeUuid(id);
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Todos.remove,
        w.finish(),
      );
    } catch (error) {
      this.core.report(error, "Todos.remove");
    }
  }

  /**
   * Chooses which items `visible` holds.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async setFilter(filter: Filter): Promise<void> {
    try {
      const w = new UndraWriter();
      FilterCodec.encode(w, filter);
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Todos.setFilter,
        w.finish(),
      );
    } catch (error) {
      this.core.report(error, "Todos.setFilter");
    }
  }

  /**
   * Flips the `done` flag of the item with `id`; unknown ids are ignored.
   * A failure is logged and passed to `onError`; the returned promise never rejects.
   */
  async toggle(id: string): Promise<void> {
    try {
      const w = new UndraWriter();
      w.writeUuid(id);
      await this.core.call(
        { target: CallTarget.ObjectMethod, handle: this.handle },
        UndraIds.Objects.Todos.toggle,
        w.finish(),
      );
    } catch (error) {
      this.core.report(error, "Todos.toggle");
    }
  }

  protected override _apply(signalId: number, op: ChangeOp, value: Uint8Array): void {
    try {
      switch (signalId) {
        case 0:
          if (op === ChangeOp.FullValue) {
            this.todos._set(decodeValue(vecTodo, value));
          } else if (op === ChangeOp.KeyedPatch) {
            const r = new UndraReader(value);
            const ops = decodePatch(r, TodoCodec);
            r.finish();
            try {
              this.todos._set(applyPatch(this.todos.peek(), ops));
            } catch (error) {
              if (!(error instanceof PatchError)) throw error;
              this._resync(0);
            }
          }
          break;
        case 1:
          if (op === ChangeOp.FullValue) {
            this.filter._set(decodeValue(FilterCodec, value));
          }
          break;
        case 2:
          if (op === ChangeOp.FullValue) {
            this.visible._set(decodeValue(vecTodo, value));
          } else if (op === ChangeOp.KeyedPatch) {
            const r = new UndraReader(value);
            const ops = decodePatch(r, TodoCodec);
            r.finish();
            try {
              this.visible._set(applyPatch(this.visible.peek(), ops));
            } catch (error) {
              if (!(error instanceof PatchError)) throw error;
              this._resync(2);
            }
          }
          break;
        case 3:
          if (op === ChangeOp.FullValue) {
            this.remaining._set(decodeValue(codecs.u32, value));
          }
          break;
        default:
          break;
      }
    } catch (error) {
      this.core.report(error, `Todos.apply(signal: ${signalId})`);
    }
  }

  /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
  private _resync(signalId: number): void {
    for (const on of [false, true]) {
      this.core.observe(this.handle, signalId, on).catch((error: unknown) => {
        this.core.report(error, `Todos.resync(signal: ${signalId})`);
      });
    }
  }
}

const vecItem = codecs.vec(ItemCodec);
const optionString = codecs.option(codecs.string);
const vecOptionString = codecs.vec(optionString);
const vecNote = codecs.vec(NoteCodec);
const vecTodo = codecs.vec(TodoCodec);
